// Server question types -> text block types (same table as paper_document.TYPE_TO_BLOCK).
export const TYPE_TO_BLOCK = {
  MCQ: 'mcq',
  TRUE_FALSE: 'true_false',
  FILL_BLANK: 'fill_blank',
  SHORT: 'short_answer',
  LONG: 'long_answer',
  ESSAY: 'essay',
  MATCHING: 'matching',
}

let counter = 0
export function newId() {
  counter += 1
  const random = Math.random().toString(16).slice(2, 8)
  return `${Date.now().toString(16).slice(-6)}${random}${counter.toString(16)}`.slice(0, 16)
}

export function blockSpec(registry, type) {
  return (registry?.blocks || []).find((spec) => spec.type === type) || null
}

export function isQuestionBlock(block, registry) {
  const spec = blockSpec(registry, block?.type)
  return spec ? spec.kind !== 'layout' : block?.type !== 'section_heading'
}

/** A fresh value for one field, from its default and kind. */
export function defaultForField(field) {
  if (field.default !== undefined) return field.default
  switch (field.kind) {
    case 'int':
    case 'number':
      return field.optional ? undefined : (field.min ?? 1)
    case 'bool':
      return false
    case 'choice':
      return field.optional ? undefined : field.choices?.[0]
    case 'text_list':
    case 'letter_rows':
      return []
    case 'list':
      return Array.from({ length: Math.max(1, field.min || 0) }, () => newListItem(field))
    case 'picture':
      return field.optional ? undefined : ''
    default:
      return field.optional ? undefined : ''
  }
}

/** One new entry for a list field (e.g. a question part, an option, a count-and-write row). */
export function newListItem(field) {
  const item = { key: newId() }
  ;(field.fields || []).forEach((sub) => {
    const value = defaultForField(sub)
    if (value !== undefined) item[sub.name] = value
  })
  // A multiple-choice part starts with four empty options, the usual paper layout.
  if ((field.fields || []).some((sub) => sub.name === 'options' && sub.kind === 'list')) {
    const optionsField = field.fields.find((sub) => sub.name === 'options')
    item.options = Array.from({ length: 4 }, () => newListItem(optionsField))
  }
  return item
}

/**
 * The list's rows with one new row per picture (``found`` from picturesFromNames). Rows still blank (no
 * picture, no text, like the first row of a new Count and write) are replaced rather than kept, so they do
 * not stop the paper saving. A count is kept inside the field's limits. ``dropped`` is what did not fit.
 */
export function rowsWithPictures(field, items, found) {
  const subs = field?.fields || []
  const pictureSub = subs.find((sub) => sub.kind === 'picture')
  const list = Array.isArray(items) ? items : []
  if (!pictureSub) return { rows: list, dropped: 0 }
  const countSub = subs.find((sub) => sub.name === 'count' && sub.kind === 'int')
  const isBlank = (item) => !item?.[pictureSub.name]
    && subs.every((sub) => !['text', 'richtext'].includes(sub.kind) || !String(item?.[sub.name] ?? '').trim())
  const kept = list.filter((item) => !isBlank(item))
  const room = Math.max(0, (field.max ?? 60) - kept.length)
  const added = (found || []).slice(0, room).map(({ picture, count }) => {
    const item = { ...newListItem(field), [pictureSub.name]: picture }
    if (countSub && Number.isFinite(count)) {
      item[countSub.name] = Math.min(Math.max(count, countSub.min ?? count), countSub.max ?? count)
    }
    return item
  })
  return { rows: [...kept, ...added], dropped: Math.max(0, (found || []).length - room) }
}

// A generic heading that depends on a setting: "Long and short" is not about the small object.
const SETTING_TITLES = { compare_objects: { mode: { length: 'Circle the long object.' } } }

/** The generic heading for a block as it is set up now. */
export function defaultTitle(block) {
  const bySetting = SETTING_TITLES[block?.type] || {}
  for (const [name, titles] of Object.entries(bySetting)) {
    const title = titles[block?.data?.[name]]
    if (title) return title
  }
  return TEXT_DEFAULT_TITLES[block?.type] || ACTIVITY_DEFAULT_TITLES[block?.type] || ''
}

/** Whether the block still has a generic heading ("Count and write."). */
export function isDefaultTitle(block) {
  const generic = TEXT_DEFAULT_TITLES[block?.type] || ACTIVITY_DEFAULT_TITLES[block?.type]
  return Boolean(block?.title) && (block.title === generic || block.title === defaultTitle(block))
}

export function newBlock(type, registry) {
  const spec = blockSpec(registry, type)
  const block = { id: newId(), type, title: TEXT_DEFAULT_TITLES[type] || ACTIVITY_DEFAULT_TITLES[type] || '' }
  if (spec?.kind === 'layout') return block
  block.marks = 5
  block.data = {}
  ;(spec?.fields || []).forEach((field) => {
    const value = defaultForField(field)
    if (value !== undefined) block.data[field.name] = value
  })
  return block
}

/**
 * A new block for a paper or a worksheet. A worksheet block starts without marks (ungraded practice). On a
 * paper it takes the marks of the last question of the same type in ``blocks``: every new question started at
 * 5 and was retyped each time (demo findings, faster 6).
 */
export function newBlockFor(kind, type, registry, blocks = []) {
  const block = newBlock(type, registry)
  if (kind === 'worksheet') {
    delete block.marks
    return block
  }
  const previous = [...(blocks || [])].reverse().find((b) => b?.type === type && Number.isFinite(Number(b.marks)) && b.marks !== '' && b.marks !== null)
  if (previous && 'marks' in block) block.marks = Number(previous.marks)
  return block
}

/**
 * The number a number box stands for once the teacher leaves it. While typing, the box keeps exactly what was
 * typed (even empty); snapping an emptied box to its minimum turned "2" into "12" in Count and write (demo findings).
 * Returns ``{ value, complete }``: ``complete`` is false while the text is empty or not a number yet.
 */
export function numberFromText(text, { min, max, integer = false, optional = false, fallback } = {}) {
  const raw = String(text ?? '').trim()
  if (raw === '' || raw === '-' || raw === '.' || Number.isNaN(Number(raw))) {
    if (optional) return { value: undefined, complete: raw === '' }
    return { value: fallback ?? min ?? 0, complete: false }
  }
  let n = Number(raw)
  if (integer) n = Math.round(n)
  if (min !== undefined && n < min) return { value: min, complete: false }
  if (max !== undefined && n > max) return { value: max, complete: false }
  return { value: n, complete: true }
}

/** "1, , 3, , 5" -> ['1', '', '3', '', '5']; without commas, spaces separate ("4 5 2 4"). */
export function splitListText(text, max = 60) {
  const raw = String(text ?? '')
  const parts = raw.includes(',') ? raw.split(',').map((part) => part.trim()) : raw.trim().split(/\s+/).filter(Boolean)
  return parts.slice(0, max)
}

/**
 * Numbers 1 to ``count`` with every ``gap``-th one left empty for the child to fill: 10 clouds took ten
 * "+ Add" clicks and five typed boxes (demo findings, faster 1). ``gap`` below 2 leaves none empty.
 */
export function countingList(count, gap = 2, max = 60) {
  const n = Math.min(Math.max(Math.trunc(Number(count)) || 0, 0), max)
  const k = Math.trunc(Number(gap)) || 0
  return Array.from({ length: n }, (_, i) => (k >= 2 && (i + 1) % k === 0 ? '' : String(i + 1)))
}

/** The block with the marks typed in the form. Empty means 0 on a paper and "no marks" where marks are optional. */
export function withMarks(block, value, optional = false) {
  const next = { ...block }
  if (value === '' || value === null || value === undefined) {
    if (optional) delete next.marks
    else next.marks = 0
  } else {
    next.marks = Number(value)
  }
  return next
}

/** Every text-block part gets a stable key, so the question id the server gives it can find its way back. */
export function withItemKeys(document) {
  return {
    ...document,
    blocks: (document?.blocks || []).map((block) => {
      const items = block?.data?.items
      if (!Array.isArray(items)) return block
      return {
        ...block,
        data: { ...block.data, items: items.map((item) => (item && typeof item === 'object' && !item.key ? { ...item, key: newId() } : item)) },
      }
    }),
  }
}

/**
 * After an autosave, copy the server's ids (block ids it made, question ids) into the document the
 * teacher may have kept editing meanwhile. Blocks are matched by id, parts by key; anything not
 * found is left alone and gets its ids on the next save.
 */
export function mergeSavedIds(local, saved) {
  const savedById = new Map((saved?.blocks || []).map((block) => [block.id, block]))
  return {
    ...local,
    blocks: (local?.blocks || []).map((block) => {
      const match = savedById.get(block.id)
      if (!match) return block
      let next = block
      if (match.question_id && match.question_id !== block.question_id) {
        next = { ...next, question_id: match.question_id }
      }
      const savedItems = new Map((match.data?.items || []).filter((i) => i?.key).map((i) => [i.key, i]))
      const items = block.data?.items
      if (Array.isArray(items) && savedItems.size) {
        let changed = false
        const merged = items.map((item) => {
          const found = item?.key ? savedItems.get(item.key) : null
          if (found?.question_id && found.question_id !== item.question_id) {
            changed = true
            return { ...item, question_id: found.question_id }
          }
          return item
        })
        if (changed) next = { ...next, data: { ...next.data, items: merged } }
      }
      return next
    }),
  }
}

export function documentMarks(document, registry) {
  return (document?.blocks || []).reduce((sum, block) => {
    if (!isQuestionBlock(block, registry)) return sum
    const marks = Number(block.marks)
    return sum + (Number.isFinite(marks) ? marks : 0)
  }, 0)
}

export function moveBlock(blocks, index, delta) {
  const target = index + delta
  if (target < 0 || target >= blocks.length) return blocks
  const next = [...blocks]
  const [moved] = next.splice(index, 1)
  next.splice(target, 0, moved)
  return next
}

/** A copy is a new question: new ids, and no link to the original's bank questions. */
export function duplicateBlock(block) {
  const copy = JSON.parse(JSON.stringify(block))
  copy.id = newId()
  delete copy.question_id
  if (Array.isArray(copy.data?.items)) {
    copy.data.items = copy.data.items.map((item) => {
      if (!item || typeof item !== 'object') return item
      const { question_id: _drop, ...rest } = item
      return { ...rest, key: newId() }
    })
  }
  return copy
}

/** Numbers shown in the outline: headings are not numbered. */
export function questionNumbers(blocks, registry) {
  let number = 0
  return (blocks || []).map((block) => (isQuestionBlock(block, registry) ? ++number : null))
}

export function blockSummary(block, registry) {
  const spec = blockSpec(registry, block?.type)
  const label = spec?.label || block?.type || 'Block'
  const items = block?.data?.items
  const rows = block?.data?.rows
  const count = Array.isArray(items) ? items.length : Array.isArray(rows) ? rows.length : null
  return count !== null ? `${label} · ${count} ${count === 1 ? 'part' : 'parts'}` : label
}

// ------------------------------------------------------------------ bank questions and photos

function pictureFromUrl(url) {
  return url ? { url } : undefined
}

/**
 * A matching question's pairs as text. The question bank form saves left_items, right_items and pairs that link
 * their indexes; the block editor saves pairs of texts. Both are read (same rule as the server's
 * paper_document.matching_pairs): an unlinked left item gets an empty right side.
 */
export function matchingPairs(typeData) {
  const pairs = (Array.isArray(typeData?.pairs) ? typeData.pairs : []).filter((pair) => pair && typeof pair === 'object')
  const lefts = typeData?.left_items
  const rights = typeData?.right_items
  if (Array.isArray(lefts) && Array.isArray(rights)) {
    const linked = new Map(pairs.filter((pair) => Number.isInteger(pair.left)).map((pair) => [pair.left, pair.right]))
    return lefts.map((left, index) => {
      const right = linked.get(index)
      return { left: String(left ?? ''), right: Number.isInteger(right) && right >= 0 && right < rights.length ? String(rights[right] ?? '') : '' }
    })
  }
  return pairs.map((pair) => ({ left: String(pair.left || ''), right: String(pair.right || '') }))
}

/** One bank or captured question (server field names) -> [questionType, item]. */
export function questionToItem(question) {
  const type = String(question?.question_type || 'SHORT').toUpperCase()
  const typeData = question?.type_data && typeof question.type_data === 'object' ? question.type_data : {}
  const item = { key: newId(), text: question?.question_text || '' }
  if (question?.id || question?.question_id) item.question_id = Number(question.question_id || question.id)
  const picture = pictureFromUrl(question?.question_image_url)
  if (type === 'MCQ') {
    const letters = ['a', 'b', 'c', 'd']
    item.options = letters
      .map((letter) => {
        const text = question?.[`option_${letter}`] ?? question?.options?.[letter.toUpperCase()] ?? ''
        const optionPicture = pictureFromUrl(question?.[`option_${letter}_image_url`])
        return text || optionPicture ? { key: newId(), text, ...(optionPicture ? { picture: optionPicture } : {}) } : null
      })
      .filter(Boolean)
    if (['A', 'B', 'C', 'D'].includes(question?.correct_answer)) item.answer = question.correct_answer
  } else if (type === 'TRUE_FALSE') {
    const answer = String(question?.correct_answer || '').toUpperCase()
    if (answer === 'TRUE' || answer === 'FALSE') item.answer = answer
  } else if (type === 'FILL_BLANK') {
    item.answers = (typeData.accepted_answers || typeData.items || []).map(String)
  } else if (type === 'MATCHING') {
    item.pairs = matchingPairs(typeData).map((pair) => ({ key: newId(), ...pair }))
  } else if (question?.answer_text) {
    item.answer = question.answer_text
  }
  if (picture && type !== 'MATCHING') item.picture = picture
  if (question?.bloom_level && type !== 'MATCHING') item.bloom_level = question.bloom_level
  return [type, item]
}

const DEFAULT_LINES = { short_answer: 2, long_answer: 8, essay: 15 }

function blockFromRun(type, rows, title, marks, attempt) {
  const blockType = TYPE_TO_BLOCK[type] || 'short_answer'
  const data = { items: rows.map(([item]) => item) }
  if (attempt && attempt < rows.length) data.attempt = attempt
  if (DEFAULT_LINES[blockType]) data.lines = DEFAULT_LINES[blockType]
  return { id: newId(), type: blockType, title: title || TEXT_DEFAULT_TITLES[blockType], marks, data }
}

function matchingBlock(item, marks, title) {
  const { pairs = [], question_id: questionId, text } = item
  return {
    id: newId(),
    type: 'matching',
    title: text ? stripTags(text) : title || TEXT_DEFAULT_TITLES.matching,
    marks,
    ...(questionId ? { question_id: questionId } : {}),
    data: { items: pairs },
  }
}

function stripTags(html) {
  return String(html || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim()
}

/** The block an activity question was saved with (the server keeps it in type_data.block), or null. */
function savedActivityBlock(question) {
  const saved = question?.type_data?.block
  return saved && typeof saved === 'object' && typeof saved.type === 'string' && saved.type ? saved : null
}

/** An activity question whose drawing was never stored: it cannot be put on a paper again. */
export function isLostActivity(question) {
  return String(question?.question_type || '').toUpperCase() === 'ACTIVITY' && !savedActivityBlock(question)
}

// The saved data is used exactly as it is (no new part keys): the server reuses the bank question
// only while its block is unchanged, and copies it otherwise.
function activityBlock(question, marks) {
  const saved = JSON.parse(JSON.stringify(savedActivityBlock(question)))
  const questionId = Number(question.question_id || question.id) || null
  const ownMarks = Number(saved.marks)
  return {
    id: newId(),
    type: saved.type,
    title: saved.title || '',
    marks: marks || (Number.isFinite(ownMarks) ? ownMarks : 0),
    ...(questionId ? { question_id: questionId } : {}),
    data: saved.data && typeof saved.data === 'object' ? saved.data : {},
  }
}

/** Consecutive questions of one type become one block (matching and activity questions one block each). */
function runsOf(rows) {
  const runs = []
  rows.forEach((row) => {
    const last = runs[runs.length - 1]
    if (last && last.type === row.type && row.type !== 'MATCHING' && row.type !== 'ACTIVITY') last.rows.push(row)
    else runs.push({ type: row.type, rows: [row] })
  })
  return runs
}

function toBlocks(rows, { title, sectionMarks, attempt } = {}) {
  const runs = runsOf(rows)
  const single = runs.length === 1
  return runs.flatMap((run) => {
    if (run.type === 'ACTIVITY') return run.rows.map((row) => row.block)
    if (run.type === 'MATCHING') return run.rows.map((row) => matchingBlock(row.item, row.marks, title))
    const marks = single && sectionMarks ? sectionMarks : run.rows.reduce((sum, row) => sum + row.marks, 0)
    return [blockFromRun(run.type, run.rows.map((row) => [row.item]), title, marks, single ? attempt : null)]
  })
}

function rowOf(question, marks) {
  const value = Number(marks ?? question?.marks ?? 1) || 0
  if (savedActivityBlock(question)) return { type: 'ACTIVITY', block: activityBlock(question, value), marks: value }
  const [type, item] = questionToItem(question)
  return { type, item, marks: value }
}

/**
 * Questions chosen in the question bank picker -> blocks to append. An activity comes back as the block it
 * was saved as; one without a saved block is left out (isLostActivity, so the picker can say how many).
 */
export function bankQuestionsToBlocks(questions) {
  return toBlocks((questions || []).filter((question) => !isLostActivity(question)).map((question) => rowOf(question, question?.marks)))
}

/** The toast after adding from the bank, naming any activity that could not be added. */
export function bankAddedMessage(questions) {
  const list = questions || []
  const lost = list.filter(isLostActivity).length
  const added = list.length - lost
  const parts = []
  if (added) parts.push(`${added} question${added === 1 ? '' : 's'} added from the bank.`)
  if (lost) {
    parts.push(lost === 1
      ? '1 activity could not be added because its drawing was not saved.'
      : `${lost} activities could not be added because their drawings were not saved.`)
  }
  return parts.join(' ')
}

/**
 * A photographed paper, as the capture review hands it over ({ structure, questions }), -> blocks.
 * Captured questions are new (no bank id yet); each section's marks and "attempt any" carry over.
 */
/** Every picture a block uses, in order (the scan review shows them as thumbnails). */
export function blockPictures(block) {
  const found = []
  const walk = (value) => {
    if (Array.isArray(value)) value.forEach(walk)
    else if (value && typeof value === 'object') {
      Object.entries(value).forEach(([key, inner]) => {
        if (key === 'picture' && inner) found.push(inner)
        else walk(inner)
      })
    }
  }
  walk(block?.data)
  return found
}

/** Blocks read by the photo scan (Paper Builder v2) as editor blocks: fresh ids, review-only keys dropped. */
export function scannedBlocksToBlocks(blocks) {
  const fresh = (blocks || []).map(({ page_number: _page, question_id: _qid, id: _id, ...block }) => ({
    ...JSON.parse(JSON.stringify(block)),
    id: newId(),
  }))
  // Text parts need their keys, as for blocks loaded from the server, so later saves can match them.
  return withItemKeys({ blocks: fresh }).blocks
}

export function capturedPaperToBlocks(prefill) {
  if (Array.isArray(prefill?.blocks)) return scannedBlocksToBlocks(prefill.blocks)
  const questions = (prefill?.questions || []).map((q) => ({ ...q, question_id: null, id: null }))
  const bySection = new Map()
  questions.forEach((question) => {
    const key = question.section_key || ''
    if (!bySection.has(key)) bySection.set(key, [])
    bySection.get(key).push(question)
  })
  const blocks = []
  const used = new Set()
  ;(prefill?.structure || []).forEach((section) => {
    if (section?.type === 'divider') {
      blocks.push({ id: newId(), type: 'section_heading', title: section.title || '' })
      return
    }
    used.add(section.key)
    const rows = (bySection.get(section.key) || []).map((q) => rowOf(q, q.marks_override ?? q.marks))
    if (!rows.length) return
    const counted = Number(section.slots_counted) || 0
    const perQuestion = Number(section.marks_per_question) || 0
    blocks.push(...toBlocks(rows, {
      title: section.instruction || TEXT_DEFAULT_TITLES[TYPE_TO_BLOCK[rows[0].type]] || section.title,
      sectionMarks: counted && perQuestion ? counted * perQuestion : null,
      attempt: counted || null,
    }))
  })
  const leftover = questions.filter((q) => !used.has(q.section_key || ''))
  blocks.push(...toBlocks(leftover.map((q) => rowOf(q, q.marks_override ?? q.marks))))
  return blocks
}

/** Server validation messages arrive as a list; the outline marks the blocks they name. */
export function problemsByQuestion(problems) {
  const map = new Map()
  ;(problems || []).forEach((problem) => {
    const match = /^Question (\d+):/.exec(problem)
    if (!match) return
    const number = Number(match[1])
    if (!map.has(number)) map.set(number, [])
    map.get(number).push(problem.replace(/^Question \d+:\s*/, ''))
  })
  return map
}

// ---- Structure step (docs/PAPER_BUILDER_STRUCTURE_PLAN.md): the paper's shape first, then its questions.
// Same rules as the server's registry.structure_lists / structure_row, so a template or a copied paper reads the
// same here and on the phone.

/** The lists a Structure row's "parts" sets: every top-level list of the block. */
export function structureLists(spec) {
  return (spec?.fields || []).filter((field) => field.kind === 'list' || field.kind === 'text_list')
}

/** One row per question of ``blocks``: type, marks, parts and choice settings (never the content). */
export function structureFromBlocks(blocks, registry) {
  return (blocks || []).filter((block) => isQuestionBlock(block, registry)).map((block) => {
    const spec = blockSpec(registry, block.type)
    const data = block.data || {}
    const row = { key: newId(), blockId: block.id, type: block.type, marks: Number(block.marks) || 0 }
    const [first] = structureLists(spec)
    if (first && Array.isArray(data[first.name])) row.parts = data[first.name].length
    const choices = {}
    ;(spec?.fields || []).forEach((field) => {
      if (field.kind === 'choice' && data[field.name] !== undefined) choices[field.name] = data[field.name]
    })
    if (Object.keys(choices).length) row.data = choices
    return row
  })
}

/** Rows from a template or another paper, as new rows (not tied to this paper's questions). */
export function freshStructureRows(rows) {
  return (rows || []).map(({ blockId, ...row }) => ({ ...row, key: newId() }))
}

export function structureTotal(rows) {
  return (rows || []).reduce((sum, row) => sum + (Number(row.marks) || 0), 0)
}

function emptyValue(field, value) {
  if (value === undefined || value === null) return true
  if (['text', 'richtext', 'picture'].includes(field.kind)) return typeof value === 'string' && !value.replace(/<[^>]*>/g, '').trim()
  return false
}

/** Whether a question still has an empty required value: same rule as the server's "still to fill". */
export function stillToFill(block, registry) {
  const spec = blockSpec(registry, block?.type)
  if (!spec || spec.kind === 'layout') return false
  const check = (fields, holder) => fields.some((field) => {
    const value = holder?.[field.name]
    if (emptyValue(field, value)) return !field.optional
    if (field.kind === 'list' && Array.isArray(value)) return value.some((item) => check(field.fields || [], item))
    return false
  })
  return check(spec.fields || [], block.data || {})
}

/** Whether a question has anything the teacher typed or chose (so removing it needs a yes). */
export function blockHasContent(block, registry) {
  const spec = blockSpec(registry, block?.type)
  const filled = (fields, holder) => fields.some((field) => {
    const value = holder?.[field.name]
    if (field.kind === 'list') return Array.isArray(value) && value.some((item) => filled(field.fields || [], item))
    if (field.kind === 'text_list') return Array.isArray(value) && value.some((entry) => String(entry ?? '').trim())
    if (['text', 'richtext', 'picture'].includes(field.kind)) return !emptyValue(field, value)
    return false
  })
  return Boolean(spec) && filled(spec.fields || [], block?.data || {})
}

function resizeList(field, list, parts) {
  const current = Array.isArray(list) ? [...list] : []
  const blank = (entry) => (field.kind === 'text_list' ? !String(entry ?? '').trim() : !filledItem(field, entry))
  while (current.length < parts) current.push(field.kind === 'text_list' ? '' : newListItem(field))
  // Only empty parts are dropped; a filled one is kept even when the row asks for fewer.
  for (let i = current.length - 1; i >= 0 && current.length > parts; i -= 1) {
    if (blank(current[i])) current.splice(i, 1)
  }
  return current
}

function filledItem(field, item) {
  return (field.fields || []).some((sub) => (sub.kind === 'list'
    ? Array.isArray(item?.[sub.name]) && item[sub.name].some((x) => filledItem(sub, x))
    : ['text', 'richtext', 'picture'].includes(sub.kind) && !emptyValue(sub, item?.[sub.name])))
}

/**
 * The paper's blocks after applying Structure ``rows``: a row tied to a question (``blockId``) updates it (marks,
 * parts, settings), a new row adds a question, a question with no row goes. Headings stay before the question they
 * came before. ``removed`` lists the questions that go; the caller asks first when one has content.
 */
export function applyStructure(blocks, rows, registry, kind = 'paper') {
  const byId = new Map((blocks || []).map((block) => [block.id, block]))
  const wanted = new Set((rows || []).map((row) => row.blockId).filter(Boolean))
  const headingsBefore = new Map()
  let pending = []
  ;(blocks || []).forEach((block) => {
    if (!isQuestionBlock(block, registry)) { pending.push(block); return }
    if (wanted.has(block.id)) { headingsBefore.set(block.id, pending); pending = [] }
  })
  const removed = (blocks || []).filter((block) => isQuestionBlock(block, registry) && !wanted.has(block.id))
  const made = []
  ;(rows || []).forEach((row) => {
    const spec = blockSpec(registry, row.type)
    if (!spec) return
    const old = row.blockId && byId.get(row.blockId)
    let block = old && old.type === row.type ? { ...old, data: { ...(old.data || {}) } } : newBlockFor(kind, row.type, registry)
    if (old && old.type !== row.type) block.id = old.id
    if (kind !== 'worksheet' || row.marks) block.marks = Number(row.marks) || 0
    const generic = isDefaultTitle(block) || !block.title
    Object.entries(row.data || {}).forEach(([name, value]) => { block.data[name] = value })
    if (generic) block.title = defaultTitle(block)
    if (Number.isInteger(row.parts) && row.parts >= 0) {
      structureLists(spec).forEach((field) => {
        block.data[field.name] = resizeList(field, block.data[field.name], Math.min(row.parts, field.max ?? 60))
      })
    }
    if (old) made.push(...(headingsBefore.get(old.id) || []))
    made.push(block)
  })
  made.push(...pending)
  return { blocks: made, removed }
}

// ---- Picking a question type (server registry TYPE_GROUPS / TYPE_PICKING). About 20 types in one flat list were slow
// to scan, so types are grouped by what the teacher wants to ask, early-years groups first for the youngest classes.

const FALLBACK_GROUPS = [
  { id: 'pictures', label: 'Activities', early: true },
  { id: 'written', label: 'Written questions', early: false },
  { id: 'layout', label: 'Layout', early: false },
]

/** Play Group, Nursery and Prep see the activity groups first (user decision 2026-11-22). */
export function isEarlyClass(className) {
  return /\b(play\s*-?\s*group|nursery|prep)\b/i.test(String(className || ''))
}

function groupOf(spec) {
  if (spec.group) return spec.group
  if (spec.kind === 'layout') return 'layout'
  return spec.kind === 'text' ? 'written' : 'pictures'
}

/**
 * The type picker's sections: "Used in this paper" first (repeats are common), then the groups, the early-years
 * ones first for an early class, Layout always last. ``search`` filters by name and hint and hides "Used".
 */
export function pickerGroups(registry, { early = false, used = [], search = '', layout = true } = {}) {
  const specs = (registry?.blocks || []).filter((spec) => layout || spec.kind !== 'layout')
  const term = String(search || '').trim().toLowerCase()
  const matches = (spec) => !term || `${spec.label} ${spec.hint || ''}`.toLowerCase().includes(term)
  const groups = registry?.type_groups?.length ? registry.type_groups : FALLBACK_GROUPS
  const content = groups.filter((group) => group.id !== 'layout')
  const ordered = [
    ...content.filter((group) => Boolean(group.early) === Boolean(early)),
    ...content.filter((group) => Boolean(group.early) !== Boolean(early)),
    ...groups.filter((group) => group.id === 'layout'),
  ]
  const sections = []
  if (!term) {
    const seen = new Set()
    const usedSpecs = (used || []).filter((type) => !seen.has(type) && seen.add(type))
      .map((type) => specs.find((spec) => spec.type === type && spec.kind !== 'layout')).filter(Boolean)
    if (usedSpecs.length) sections.push({ id: 'used', label: 'Used in this paper', types: usedSpecs })
  }
  ordered.forEach((group) => {
    const types = specs.filter((spec) => groupOf(spec) === group.id && matches(spec))
    if (types.length) sections.push({ id: group.id, label: group.label, types })
  })
  return sections
}
